226	    <div class="searchbar">
227	      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
228	        <circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/>
229	      </svg>
