288	<script>
289	const $ = s => document.querySelector(s);
290	const qEl = $('#q'), resEl = $('#results'), statusEl = $('#status');
291	let order = 'relevance', kind = 'all', mode = 'hybrid', terms = [], seq = 0, canAnswer = true;
292	let startedAt = null;
293	
294	// 改完代码重启服务，开着的页面还跑着旧 JS——看着就像「改了没生效」。
295	// 服务每次响应都带自己的启动时刻，跟页面记下的对不上就摆条提示。
296	function noteServerRestart(ts){
297	  if (!ts) return;
298	  if (startedAt === null){ startedAt = ts; return; }
