679	function hitNode(mx, my){
680	  if (!G.data) return null;
681	  let best = null, bestD = 14;
682	  for (const n of G.data.nodes){
683	    if (!visibleNode(n)) continue;
684	    const [x,y] = toXY(n);
685	    const d = Math.hypot(mx-x, my-y);
686	    if (d < bestD){ best = n; bestD = d; }
687	  }
688	  return best;
689	}
690	
691	function drawGraph(){
692	  if (!G.data) return;
693	  const dpr = window.devicePixelRatio || 1;
694	  const w = canvas.clientWidth, h = canvas.clientHeight;
695	  if (canvas.width !== w*dpr || canvas.height !== h*dpr){
696	    canvas.width = w*dpr; canvas.height = h*dpr;
697	  }
698	  const ctx = canvas.getContext('2d');
699	  ctx.setTransform(dpr,0,0,dpr,0,0);
700	  ctx.clearRect(0,0,w,h);
701	
702	  const vis = new Set(G.data.nodes.filter(visibleNode).map(n => n.id));
703	  const sel = G.sel && vis.has(G.sel) ? G.sel : null;
704	  const neigh = new Set();
705	  if (sel){
706	    for (const e of G.data.edges){
707	      if (G.edge === 'cite' && e.type !== 'cite') continue;
708	      if (e.source === sel && vis.has(e.target)) neigh.add(e.target);
709	      if (e.target === sel && vis.has(e.source)) neigh.add(e.source);
710	    }
711	  }
712	
713	  // 簇名
714	  ctx.font = '600 12px -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif';
715	  for (const c of G.data.communities){
716	    const members = G.data.nodes.filter(n => n.community === c.id && vis.has(n.id));
717	    if (!members.length) continue;
718	    const [x,y] = toXY({x:c.x, y:c.y});
719	    ctx.fillStyle = commColor(c.id, .14);
720	    ctx.beginPath(); ctx.arc(x, y, 28 + Math.sqrt(members.length)*6, 0, Math.PI*2); ctx.fill();
721	    ctx.fillStyle = commColor(c.id, .85);
722	    ctx.textAlign = 'center';
723	    ctx.fillText(c.label, x, y - 34 - Math.sqrt(members.length)*3);
724	  }
725	
726	  for (const e of G.data.edges){
727	    if (G.edge === 'cite' && e.type !== 'cite') continue;
728	    if (!vis.has(e.source) || !vis.has(e.target)) continue;
729	    const a = G.byId[e.source], b = G.byId[e.target];
730	    const hot = sel && (e.source === sel || e.target === sel);
731	    if (e.type !== 'cite' && !hot) continue;   // 近邻边太多，只在点中一篇时画
732	    if (!a || !b) continue;
733	    const [x1,y1] = toXY(a), [x2,y2] = toXY(b);
734	    ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2);
735	    ctx.strokeStyle = e.type === 'cite'
736	      ? (hot ? 'rgba(15,114,100,.7)' : 'rgba(15,114,100,.22)')
737	      : (hot ? 'rgba(139,92,246,.55)' : 'rgba(139,92,246,.12)');
738	    ctx.lineWidth = hot ? 1.6 : 1;
739	    if (e.type !== 'cite') ctx.setLineDash([4,4]); else ctx.setLineDash([]);
740	    ctx.stroke();
741	    ctx.setLineDash([]);
742	  }
743	
744	  for (const n of G.data.nodes){
745	    if (!vis.has(n.id)) continue;
746	    const [x,y] = toXY(n);
747	    const r = n.id === sel ? 7.5 : (neigh.has(n.id) ? 5.5 : 3.8);
748	    const dim = sel && n.id !== sel && !neigh.has(n.id);
749	    ctx.beginPath(); ctx.arc(x,y,r,0,Math.PI*2);
750	    ctx.fillStyle = commColor(n.community, dim ? .22 : 1);
751	    ctx.fill();
752	    if (n.id === sel || neigh.has(n.id) || G.q){
753	      ctx.fillStyle = dim ? 'rgba(92,85,75,.4)' : getComputedStyle(document.body).getPropertyValue('--ink') || '#1d1a16';
754	      ctx.font = (n.id === sel ? '600 12.5px ' : '12px ') + '-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif';
755	      ctx.textAlign = 'left';
756	      ctx.fillText(n.short.slice(0,16), x + r + 5, y + 4);
757	    }
758	  }
759	}
760	
761	function showGraphInfo(n){
762	  if (!n){
763	    const st = G.data && G.data.stats;
764	    ginfo.innerHTML = st
765	      ? `<p class="ghint">${st.articles} 篇，${st.communities} 个主题簇。互链 ${st.cites} 条，题义近邻 ${st.similar} 条。点一篇看它连着谁。</p>`
766	      : `<p class="ghint">点一篇，看它引用了谁、题义上挨着谁。滚轮缩放，拖空白处平移。</p>`;
767	    return;
768	  }
769	  const cites = [], sims = [];
770	  for (const e of G.data.edges){
771	    const other = e.source === n.id ? e.target : (e.target === n.id ? e.source : null);
772	    if (!other) continue;
773	    const o = G.byId[other];
774	    if (!o) continue;
775	    (e.type === 'cite' ? cites : sims).push(o);
776	  }
777	  const row = (o) => `<button class="gn" data-id="${esc(o.id)}">${esc(o.short)}</button>`;
778	  ginfo.innerHTML = `
779	    <h3><a href="${esc(n.link)}" target="_blank" rel="noopener">${esc(n.title)}</a></h3>
780	    <p class="gmeta">${n.date || ''}${n.kind==='comic' ? ' · 漫画' : ''} · ${G.data.communities[n.community]?.label || ''}</p>
781	    ${cites.length ? `<div class="gsec">文里点名引用</div>${cites.map(row).join('')}` : ''}
782	    ${sims.length ? `<div class="gsec">题义接近</div>${sims.map(row).join('')}` : ''}
783	    ${!cites.length && !sims.length ? `<p class="ghint">这篇暂时没连上别人。</p>` : ''}
784	    <div class="actions" style="margin-top:14px"></div>`;
785	  const actions = ginfo.querySelector('.actions');
786	  const open = document.createElement('a');
787	  open.className = 'btn primary'; open.href = n.link; open.target = '_blank'; open.rel = 'noopener';
788	  open.textContent = '打开原文';
789	  actions.appendChild(open);
790	  ginfo.querySelectorAll('.gn').forEach(b => b.onclick = () => {
791	    G.sel = b.dataset.id; showGraphInfo(G.byId[G.sel]); drawGraph();
792	  });
793	}
794	
795	canvas.addEventListener('pointerdown', e => {
796	  const r = canvas.getBoundingClientRect();
797	  const n = hitNode(e.clientX - r.left, e.clientY - r.top);
798	  if (n){ G.sel = n.id; showGraphInfo(n); drawGraph(); return; }
799	  G.drag = {x: e.clientX - G.ox, y: e.clientY - G.oy};
800	  canvas.setPointerCapture(e.pointerId);
801	});
802	canvas.addEventListener('pointermove', e => {
803	  const r = canvas.getBoundingClientRect();
804	  if (G.drag){ G.ox = e.clientX - G.drag.x; G.oy = e.clientY - G.drag.y; drawGraph(); return; }
805	  const n = hitNode(e.clientX - r.left, e.clientY - r.top);
806	  canvas.style.cursor = n ? 'pointer' : 'grab';
807	});
808	canvas.addEventListener('pointerup', () => { G.drag = null; });
809	canvas.addEventListener('wheel', e => {
810	  e.preventDefault();
811	  const r = canvas.getBoundingClientRect();
812	  const mx = e.clientX - r.left, my = e.clientY - r.top;
813	  const old = G.scale;
814	  G.scale = Math.min(3.2, Math.max(0.45, G.scale * (e.deltaY < 0 ? 1.12 : 0.89)));
815	  G.ox = mx - (mx - G.ox) * (G.scale / old);
816	  G.oy = my - (my - G.oy) * (G.scale / old);
817	  drawGraph();
818	}, {passive:false});
819	window.addEventListener('resize', () => { if (! $('#graph-panel').hidden) drawGraph(); });
820	
821	</script>
822	</body>
823	</html>
