334	const PRESET_DEFS = [
335	  {id:'nondeterminism',section:'3.5',title:'同一句话问三遍'},
336	  {id:'temperature',section:'3.6',title:'温度拧到底，再拧到顶'},
337	  {id:'top_p',section:'3.7',title:'top_p 放小，再放到 1'},
338	  {id:'max_tokens',section:'3.8',title:'上限设成 50'},
339	  {id:'cutoff',section:'3.3',title:'知识停在哪一天'},
340	  {id:'cot',section:'3.10',title:'加一句「请一步一步来」'},
341	  {id:'align',section:'2.10',title:'让它把系统设定交出来'},
342	];
343	let PRESET_DATA = {};
