365	    $('#cmpLabel').textContent = p.compare.field === 'prompt_suffix'
366	      ? '对照跑：一次什么都不加，一次在后面加一句' : '对照跑：' + p.compare.field + ' 取两个值';
367	    $('#cmpA').value = p.compare.a ?? '';
368	    $('#cmpB').value = p.compare.b ?? '';
369	  }
