371	  $('#cmpToggle').hidden = !p.compare;
372	  $('#cmpToggle').textContent = cmpOn ? '关掉对照' : '开对照';
373	  $('#paramWatch').hidden = false;
374	  $('#paramWatch').textContent = '看这个：' + p.watch;
