378	function updateCost(){
379	  const n = Math.max(1, Math.min(+$('#n').value || 1, 5));
380	  const mult = (cur && cur.compare && cmpOn) ? 2 : 1;
381	  $('#paramCost').textContent = `这一下要发 ${n * mult} 遍，扣 ${n * mult} 次额度`;
382	}
