391	$('#paramGo').onclick = async () => {
392	  const btn = $('#paramGo');
393	  btn.disabled = true; btn.textContent = '发出去了，等它写…';
394	  $('#paramOut').innerHTML = '<p class="spin">正在等它写完。对照跑是两组一起发，会慢一点。</p>';
395	  const num = v => { const t = (v || '').trim(); return t === '' ? null : (isNaN(+t) ? t : +t); };
396	  const body = {
397	    preset: cur ? cur.id : '',
398	    prompt: $('#prompt').value,
399	    system: $('#system').value,
400	    temperature: num($('#temp').value),
401	    top_p: num($('#topp').value),
