415	    const d = await r.json();
416	    if (r.status === 429){ $('#paramOut').innerHTML = `<div class="err">${esc(d.error)}</div>`; }
417	    else drawParam(d);
418	    if (d.quota) { STATUS = d.quota; refreshStatus(); }
419	  }catch(e){
420	    $('#paramOut').innerHTML = `<div class="err">没发出去：${esc(e.message)}</div>`;
421	  }
