423	};
424	
425	function drawParam(d){
426	  if (d.error) return $('#paramOut').innerHTML = `<div class="err">${esc(d.error)}</div>`;
427	  if (d.degraded) return $('#paramOut').innerHTML = fromBook(d);
428	  let html = '';
429	  if (d.ran_out) html += `<div class="err">${esc(d.ran_out)}</div>`;
430	  html += `<div class="groups${d.groups.length > 1 ? ' two' : ''}">` + d.groups.map(g => `
431	    <div class="group">
432	      <h4>${esc(g.label)}<em>${g.runs.length} 遍・不一样的 ${g.distinct} 种</em></h4>
433	      ${g.runs.map((r, i) => r.ok ? `
434	        <div class="run">${esc(r.text) || '<em style="color:var(--ink-3)">它什么都没说</em>'}
435	          <span class="meta">第 ${i + 1} 遍・${r.ms} 毫秒・输出 ${r.completion_tokens ?? '?'} token${
436	            r.finish_reason === 'length' ? '・<span class="cut">写到上限被切断了</span>' : ''}</span></div>`
437	        : `<div class="run"><span class="cut">${esc(r.error)}</span></div>`).join('')}
438	    </div>`).join('') + '</div>';
439	  const notes = d.groups.filter(g => g.runs.length > 1).map(g =>
440	    g.all_same ? `「${esc(g.label)}」那几遍<b>一字不差</b>。`
441	               : `「${esc(g.label)}」${g.runs.length} 遍给出了 ${g.distinct} 种不同的答案。`);
442	  const cut = d.groups.some(g => g.runs.some(r => r.finish_reason === 'length'));
443	  if (cut) notes.push('有一组的 finish_reason 是 length——它不是不会答，是这一次的额度写完了。');
444	  if (notes.length) html += `<div class="verdict">${notes.join(' ')}</div>`;
445	  $('#paramOut').innerHTML = html;
446	}
447	
448	function fromBook(d){
449	  const rec = d.record;
450	  return `<div class="frombook">
451	    <h4>${esc(d.reason)}，下面是书里 ${esc(rec.section)} 节那次的实测记录</h4>
452	    <p style="margin:0 0 10px;color:var(--ink-2)">这是她写书时跑的那一次，不是你刚才这次。${esc(rec.note)}</p>
453	    ${rec.groups.map(g => `<div style="margin:0 0 8px"><b>${esc(g.label)}</b>
454	      <div style="margin-top:4px">${g.runs.map(t => `<div class="run" style="border:0;padding:3px 0">${esc(t)}</div>`).join('')}</div>
455	    </div>`).join('')}
456	    <p style="margin:10px 0 0">${esc(rec.conclusion)}</p></div>`;
457	}
458	
459	// ── 计时台 ───────────────────────────────────────────────
460	let MATERIAL = null;
461	async function loadMaterial(){
462	  try{
463	    const r = await fetch('/api/lab/material');
464	    if (!r.ok) return;
465	    MATERIAL = await r.json();
466	    if (MATERIAL.ok) $('#matNote').textContent =
