470	
471	function runTiming(which){
472	  const q = $('#tq').value.trim();
473	  if (!q) return;
474	  const box = $(which === 1 ? '#s1' : '#s2');
475	  const body = box.querySelector('.body');
476	  body.textContent = ''; box.querySelector('.ttft').textContent = '…';
477	  box.querySelector('.total').textContent = '…'; box.querySelector('.chars').textContent = '…';
478	  box.querySelector('.bar .wait').style.width = '0'; box.querySelector('.bar .gen').style.width = '0';
479	  $('#timingVerdict').innerHTML = '';
480	  const es = new EventSource(`/api/lab/timing?q=${encodeURIComponent(q)}&ctx=${which === 2 ? 1 : 0}`);
481	  let ttft = null;
482	  es.onmessage = ev => {
483	    const d = JSON.parse(ev.data);
484	    if (d.type === 'degraded'){
485	      body.innerHTML = fromBook({reason: d.reason, record: d.record});
486	      es.close();
487	    } else if (d.type === 'meta'){
488	      box.querySelector('h4').textContent = which === 1
489	        ? `空着问・发过去 ${d.input_chars} 字`
490	        : `贴了《${d.ctx_title}》前 ${d.ctx_chars} 字・发过去 ${d.input_chars} 字`;
491	    } else if (d.type === 'delta'){
492	      if (ttft === null){ ttft = d.ttft_ms; box.querySelector('.ttft').textContent = ttft + ' ms'; }
493	      body.textContent += d.text; body.scrollTop = body.scrollHeight;
494	    } else if (d.type === 'error'){
495	      body.innerHTML = `<span style="color:var(--err)">${esc(d.text)}</span>`; es.close();
496	    } else if (d.type === 'done'){
497	      if (d.total_ms){
498	        box.querySelector('.total').textContent = (d.total_ms / 1000).toFixed(1) + ' s';
499	        box.querySelector('.chars').textContent = d.chars + ' 字';
500	        const w = Math.round((d.ttft_ms || 0) / d.total_ms * 100);
501	        box.querySelector('.bar .wait').style.width = w + '%';
502	        box.querySelector('.bar .gen').style.width = (100 - w) + '%';
503	        box.dataset.ttft = d.ttft_ms; box.dataset.total = d.total_ms;
504	        compareTiming();
505	      }
506	      es.close();
507	    }
508	  };
509	  es.onerror = () => es.close();
510	}
511	$('#tGo1').onclick = () => runTiming(1);
512	$('#tGo2').onclick = () => runTiming(2);
513	
514	function compareTiming(){
515	  const a = $('#s1').dataset.ttft, b = $('#s2').dataset.ttft;
516	  if (!a || !b) return;
517	  const ratio = (b / a).toFixed(1);
518	  $('#timingVerdict').innerHTML = `<div class="verdict">
519	    贴了三千字之后，第一个字慢了 <b>${ratio} 倍</b>（${a} ms → ${b} ms）。
520	    这就是书里 2.6 节说的：发过去的东西越长，长的是开口之前那一段。</div>`;
521	}
522	
523	// ── 切法台 ───────────────────────────────────────────────
524	document.querySelectorAll('[data-fill]').forEach(b => b.onclick = () => {
525	  if (b.dataset.fill === 'name') $('#ctext').value = '静姐一家\n小胖蟹';
526	  else $('#ctext').value = LONG_SAMPLE;
527	  $('#chunkGo').click();
528	});
529	
530	const LONG_SAMPLE = `## 为什么要切
531	
532	长文章要先切成一段一段，检索的时候是按块找的，不是按整篇找。模型一次看得下的有限，而且整篇一起算相似度，重点会被稀释。一篇三千字的文章里只有一段讲你要的事，那一段的信号会被另外两千九百字盖掉。
533	
534	## 常见的切法
535	
536	按固定字数切最省事，也最容易把一句话拦腰截断。按段落和标题切，顺着作者本来的分法走，多数时候够用。让两块之间留一点重叠，前一块的结尾抄进后一块的开头，防的就是重要的话正好断在缝上。
537	
538	## 有一个坑值得单说
539	
540	切开之后，每一块都不知道自己是谁了。一块内容写着「这个按上次说的办」，它被单独捞出来的时候，「上次」是谁，没人知道了。解决办法是切的时候给每一块补上出处，哪篇文章、哪个小标题下面的。这一步很便宜，效果很明显。
541	
542	## 切错了不报错
543	
544	切得太碎，一段话的意思断在中间；切得太大，重点被稀释。它不会告诉你切错了，你只会发现怎么搜不着。`;
545	
