556	function drawChunk(d){
557	  if (d.error) return $('#chunkOut').innerHTML = `<div class="err">${esc(d.error)}</div>`;
558	  const t = d.tokens, c = d.chunks, lib = d.library;
559	  let html = '';
560	
561	  html += `<div class="card"><h3>它眼里的最小单位（书里 2.4 节）</h3>
562	    <p class="hint">这 ${t.chars} 个字符里有 ${t.cjk} 个汉字，存成 UTF-8 是 ${t.bytes} 个字节。
563	      下面两份都是真词表，不是估的。紫色那种是半个字——词表里没收这个字，它被按字节劈开了。</p>`;
564	  if (!t.ok){
565	    html += `<div class="err">词表没加载起来：${esc(t.error)}</div>`;
566	  } else {
567	    t.vocabs.forEach(v => {
568	      html += `<div style="margin:16px 0 0"><b>${esc(v.label)}</b>
569	        <span style="color:var(--ink-3);font-size:12.5px">（${esc(v.name)}）</span>
570	        <span style="float:right;font-weight:650;color:var(--accent)">${v.count} 个 token</span>
571	        <div style="clear:both"></div>
572	        <div style="color:var(--ink-3);font-size:12.5px">${esc(v.note)}${
573	          v.split_chars ? `・这段里有 <b style="color:var(--byte)">${v.split_chars}</b> 片是被劈开的半个字` : ''}</div>
574	        <div class="toks">${v.pieces.map(p => p.whole
575	          ? `<span class="tok${p.text.trim() ? '' : ' sp'}">${esc(p.text) || '␣'}</span>`
576	          : `<span class="tok part">${esc(p.text)}</span>`).join('')}</div></div>`;
577	    });
578	    if (t.ratio && t.ratio !== '1.0')
579	      html += `<div class="verdict">同一段字，上一代那份词表切出来是新词表的 <b>${t.ratio} 倍</b>。
580	        拿 token 数跨厂商比大小，比不出什么——各家一个 token 装的东西不一样。</div>`;
581	    html += `<p class="hint" style="margin:14px 0 0">另外还有一笔你打不出来的账：
582	      每轮对话都要带一段你看不见的模板（<code>&lt;|im_start|&gt;</code> 那一串），
583	      光这段模板本身就是 ${t.template_overhead} 个 token。书里那次量的是七个汉字算成 18 个。</p>`;
584	  }
585	  html += '</div>';
586	
587	  html += `<div class="card"><h3>切成块（书里 6.5 节）</h3>
588	    <p class="hint">用的就是那个库自己的切法：按段落和标题走，目标 ${c.target} 字一块，
589	      单段超过 ${c.hard_max} 字硬切，两块之间留一点重叠。</p>
590	    <table><tr><th>一块多长</th><th class="n">多少块</th></tr>
591	      <tr><td>200 到 500 字</td><td class="n big">${c.buckets['200_500']}</td></tr>
592	      <tr><td>30 到 200 字</td><td class="n">${c.buckets['30_200']}</td></tr>
593	      <tr><td>500 字以上</td><td class="n">${c.buckets.gt500}</td></tr>
594	      <tr><td>不到 30 字</td><td class="n">${c.buckets.lt30}</td></tr></table>
595	    <p class="hint" style="margin-top:12px">${c.chars} 个字切成了 ${c.total} 块。${
596	      c.fell_back ? '<b style="color:var(--err)">这段字切不出块——按段落走走到头也没凑够 30 字，'
597	        + '只好把整段当一块。书里那 18 个不到 30 字的块就是这么来的：正文本来就是图，没字可切。</b>' : ''}</p>
598	    <div class="blocks">${c.chunks.map(b => `<div class="block${b.len < 30 ? ' tiny' : ''}">
599	      <div class="top"><span>${b.heading ? esc(b.heading) : '（没有小标题）'}</span><span>${b.len} 字</span></div>
600	      ${esc(b.preview)}${b.len > 120 ? '…' : ''}</div>`).join('')}</div></div>`;
601	
602	  if (lib && lib.chunks){
603	    html += `<div class="card"><h3>顺带看一眼这个库自己被切成了什么样</h3>
604	      <p class="hint">${lib.docs} 篇文章和漫画，切出 ${lib.chunks} 个块，中位数一块 ${lib.median} 字。
605	        现算的，不是书里抄的。</p>
606	      <table><tr><th>一块多长</th><th class="n">多少块</th></tr>
607	        <tr><td>200 到 500 字</td><td class="n big">${lib.buckets['200_500']}</td></tr>
608	        <tr><td>30 到 200 字</td><td class="n">${lib.buckets['30_200']}</td></tr>
609	        <tr><td>500 字以上</td><td class="n">${lib.buckets.gt500}</td></tr>
610	        <tr><td>不到 30 字</td><td class="n">${lib.buckets.lt30}</td></tr></table>`;
611	    if (lib.shortest.length)
612	      html += `<p class="hint" style="margin-top:12px">最短的那几块长这样——
613	        这几块在库里等于不存在，跟任何一个问题算相似度都不像，永远排不进前几条：</p>
614	        <div class="blocks">${lib.shortest.map(s => `<div class="block tiny">
615	          <div class="top"><span>${esc(s.kind)}</span><span>${s.text.length} 字</span></div>
616	          ${esc(s.text)}</div>`).join('')}</div>`;
617	    html += '</div>';
618	  }
619	  $('#chunkOut').innerHTML = html;
620	}
